/// `POST /v2/git/stage` and `POST /v2/git/unstage`: exactly one of a
/// non-empty `files` or `all`.
public struct GitIndexRequest: Codable, Equatable, Sendable {
    public var requestId: String
    public var path: String
    public var expected: GitPreconditions
    public var files: [GitFileRef]
    public var all: [GitChangeArea]?
    /// Stage conflicted files that still contain conflict markers. Sent only
    /// when true, and only to a Mac advertising `gitStageResolved`: an older
    /// Mac's contract closes the object.
    public var confirmConflictMarkers: Bool

    public init(
        requestId: String, path: String, expected: GitPreconditions,
        files: [GitFileRef] = [], all: [GitChangeArea]? = nil,
        confirmConflictMarkers: Bool = false
    ) {
        self.requestId = requestId
        self.path = path
        self.expected = expected
        self.files = files
        self.all = all
        self.confirmConflictMarkers = confirmConflictMarkers
    }

    private enum CodingKeys: String, CodingKey {
        case requestId, path, expected, files, all, confirmConflictMarkers
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        requestId = try container.decode(String.self, forKey: .requestId)
        path = try container.decode(String.self, forKey: .path)
        expected = try container.decode(GitPreconditions.self, forKey: .expected)
        files = try container.decodeIfPresent([GitFileRef].self, forKey: .files) ?? []
        all = try container.decodeIfPresent([GitChangeArea].self, forKey: .all)
        confirmConflictMarkers =
            try container.decodeIfPresent(Bool.self, forKey: .confirmConflictMarkers) ?? false
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(requestId, forKey: .requestId)
        try container.encode(path, forKey: .path)
        try container.encode(expected, forKey: .expected)
        try container.encode(files, forKey: .files)
        try container.encodeIfPresent(all, forKey: .all)
        if confirmConflictMarkers {
            try container.encode(true, forKey: .confirmConflictMarkers)
        }
    }
}

