/// `POST /v2/git/push`: the source, remote and destination exactly as the
/// push review showed them. `remoteUrl` and `destinationOid` are sent as
/// null when absent, as the schema requires.
public struct GitPushRequest: Codable, Equatable, Sendable {
    public var requestId: String
    public var path: String
    public var expected: GitPreconditions
    public var remote: String
    public var remoteUrl: String?
    public var destination: String
    public var sourceBranch: String
    public var sourceOid: String
    public var destinationOid: String?

    public init(
        requestId: String, path: String, expected: GitPreconditions, remote: String,
        remoteUrl: String?, destination: String, sourceBranch: String, sourceOid: String,
        destinationOid: String?
    ) {
        self.requestId = requestId
        self.path = path
        self.expected = expected
        self.remote = remote
        self.remoteUrl = remoteUrl
        self.destination = destination
        self.sourceBranch = sourceBranch
        self.sourceOid = sourceOid
        self.destinationOid = destinationOid
    }

    private enum CodingKeys: String, CodingKey {
        case requestId, path, expected, remote, remoteUrl, destination, sourceBranch, sourceOid,
            destinationOid
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(requestId, forKey: .requestId)
        try container.encode(path, forKey: .path)
        try container.encode(expected, forKey: .expected)
        try container.encode(remote, forKey: .remote)
        try container.encode(remoteUrl, forKey: .remoteUrl)
        try container.encode(destination, forKey: .destination)
        try container.encode(sourceBranch, forKey: .sourceBranch)
        try container.encode(sourceOid, forKey: .sourceOid)
        try container.encode(destinationOid, forKey: .destinationOid)
    }
}

