    }
}

public enum ConversationItemKind: Equatable, Sendable, Codable {
    case message(role: String, text: String, status: MessageStatus)
    case tool(name: String, summary: String, status: String, parentMessageId: String?)
    case request(requestId: String, requestType: String, prompt: String, choices: [String], status: String, questions: [RequestQuestion] = [])
    /// A kind this build cannot present: a `type` added after it shipped, or a
    /// known `type` whose fields do not decode. `type` is the wire value when
    /// it was readable. Forward compatibility is a property of the installed
    /// client, so this degrades to a neutral row rather than failing the batch
    /// or the socket.
    case unrecognized(type: String?)

    private enum CodingKeys: String, CodingKey {
        case type, role, text, status, name, summary, parentMessageId
        case requestId, requestType, prompt, choices, questions
    }

    /// Never throws: an unreadable kind becomes `.unrecognized`.
    public init(from decoder: Decoder) {
        guard let container = try? decoder.container(keyedBy: CodingKeys.self) else {
            self = .unrecognized(type: nil)
            return
        }
        let type = try? container.decode(String.self, forKey: .type)
        self = (try? Self.known(type, in: container)) ?? .unrecognized(type: type)
    }

    private static func known(_ type: String?, in container: KeyedDecodingContainer<CodingKeys>) throws -> Self {
        switch type {
        case "message":
            return .message(
                role: try container.decode(String.self, forKey: .role),
                text: try container.decode(String.self, forKey: .text),
                status: try container.decode(MessageStatus.self, forKey: .status)
            )
        case "tool":
            return .tool(
                name: try container.decode(String.self, forKey: .name),
                summary: try container.decode(String.self, forKey: .summary),
                status: try container.decode(String.self, forKey: .status),
                parentMessageId: try container.decodeIfPresent(String.self, forKey: .parentMessageId)
            )
        case "request":
            return .request(
                requestId: try container.decode(String.self, forKey: .requestId),
                requestType: try container.decode(String.self, forKey: .requestType),
                prompt: try container.decode(String.self, forKey: .prompt),
                choices: try container.decode([String].self, forKey: .choices),
                status: try container.decode(String.self, forKey: .status),
                questions: try container.decodeIfPresent([RequestQuestion].self, forKey: .questions) ?? []
            )
        default:
            throw DecodingError.dataCorruptedError(forKey: .type, in: container, debugDescription: "unknown conversation item kind")
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .message(let role, let text, let status):
            try container.encode("message", forKey: .type)
            try container.encode(role, forKey: .role)
            try container.encode(text, forKey: .text)
            try container.encode(status, forKey: .status)
        case .tool(let name, let summary, let status, let parentMessageId):
            try container.encode("tool", forKey: .type)
            try container.encode(name, forKey: .name)
            try container.encode(summary, forKey: .summary)
            try container.encode(status, forKey: .status)
            try container.encodeIfPresent(parentMessageId, forKey: .parentMessageId)
        case .request(let requestId, let requestType, let prompt, let choices, let status, let questions):
            try container.encode("request", forKey: .type)
            try container.encode(requestId, forKey: .requestId)
            try container.encode(requestType, forKey: .requestType)
            try container.encode(prompt, forKey: .prompt)
            try container.encode(choices, forKey: .choices)
            if !questions.isEmpty { try container.encode(questions, forKey: .questions) }
            try container.encode(status, forKey: .status)
        case .unrecognized(let type):
            // Round-trips through the store cache back to `.unrecognized`.
            try container.encodeIfPresent(type, forKey: .type)
        }
    }
}

public struct ConversationItem: Codable, Equatable, Identifiable, Sendable {
    public let id: String
    public let ordinal: UInt64
    /// Display metadata only. Clients order by ordinal.
    public let createdAt: String
    public let kind: ConversationItemKind
}

/// Per-frame count of item elements that could not be presented. The socket
/// installs a fresh tally under `CodingUserInfoKey.conversationDecodeTally`
/// before each decode, so degradation is counted rather than silent.
public final class ConversationDecodeTally {
    /// Elements rendered as an `.unrecognized` placeholder row.
    public internal(set) var unrecognizedItems = 0
    /// Elements without a readable `id` and `ordinal`: they cannot be placed
    /// or deduplicated, so they are omitted and only counted.
    public internal(set) var droppedItems = 0

    public init() {}
}

extension CodingUserInfoKey {
    public static let conversationDecodeTally = CodingUserInfoKey(rawValue: "latch.conversationDecodeTally")!
}

/// One element of a wire item list. Decoding never throws, so one bad element
/// cannot fail the whole batch. A failed element keeps its `id` and `ordinal`
/// when those are still readable, so ordering and dedup keep working.
struct TolerantConversationItem: Decodable {
    let item: ConversationItem?

    private enum CodingKeys: String, CodingKey { case id, ordinal, createdAt, kind }
    private enum KindKeys: String, CodingKey { case type }

    init(from decoder: Decoder) {
        let tally = decoder.userInfo[.conversationDecodeTally] as? ConversationDecodeTally
        if let decoded = try? ConversationItem(from: decoder) {
            if case .unrecognized = decoded.kind { tally?.unrecognizedItems += 1 }
            item = decoded
            return
        }
        guard let container = try? decoder.container(keyedBy: CodingKeys.self),
              let id = try? container.decode(String.self, forKey: .id),
              let ordinal = try? container.decode(UInt64.self, forKey: .ordinal)
        else {
            tally?.droppedItems += 1
            item = nil
            return
        }
        tally?.unrecognizedItems += 1
        let kind = try? container.nestedContainer(keyedBy: KindKeys.self, forKey: .kind)
        item = ConversationItem(
            id: id,
            ordinal: ordinal,
            createdAt: (try? container.decode(String.self, forKey: .createdAt)) ?? "",
            kind: .unrecognized(type: try? kind?.decode(String.self, forKey: .type))
        )
    }
}

extension KeyedDecodingContainer {
    func decodeConversationItems(forKey key: Key) throws -> [ConversationItem] {
        try decode([TolerantConversationItem].self, forKey: key).compactMap { $0.item }
    }
}

public struct OperationAvailability: Codable, Equatable, Sendable {
    public let enabled: Bool
    public let reason: String?
}

public struct ConnectorIdentity: Codable, Equatable, Sendable {
    public let id: String
    public let version: String
}

/// A slash command the agent advertises, as the Hub relays its bridge's catalog.
public struct AdvertisedCommand: Codable, Equatable, Sendable {
    public let name: String
    public let description: String
    public let source: String?
}

public struct ConversationState: Codable, Equatable, Sendable {
    public let phase: String
    public let sendMessage: OperationAvailability
    public var cancelTurn: OperationAvailability? = nil
    public let resolveRequest: OperationAvailability
    /// Derived from the newest pending request item.
    public let pendingRequest: String?
    public let connector: ConnectorIdentity?
    /// Why the agent closed its newest turn (answer, aborted, refusal, error),
    /// carried only while no turn is open. Nil when the Hub has no outcome.
    public var turnOutcome: String? = nil
    /// Slash commands a live bridge advertises. Nil when the Hub does not
    /// know them, which is not the same as none.
    public var commands: [AdvertisedCommand]? = nil
}

public struct ConversationSnapshot: Codable, Equatable, Sendable {
    public let generation: String
    public let revision: UInt64
    public let operationEpoch: String
    public let items: [ConversationItem]
    public let state: ConversationState
    public let hasMoreBefore: Bool
    public let reason: String?
}

extension ConversationSnapshot {
    private enum TolerantKeys: String, CodingKey {
        case generation, revision, operationEpoch, items, state, hasMoreBefore, reason
    }

    /// Declared in an extension so the memberwise initializer survives.
    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: TolerantKeys.self)
        self.init(
            generation: try container.decode(String.self, forKey: .generation),
            revision: try container.decode(UInt64.self, forKey: .revision),
            operationEpoch: try container.decode(String.self, forKey: .operationEpoch),
            items: try container.decodeConversationItems(forKey: .items),
            state: try container.decode(ConversationState.self, forKey: .state),
            hasMoreBefore: try container.decode(Bool.self, forKey: .hasMoreBefore),
            reason: try container.decodeIfPresent(String.self, forKey: .reason)
        )
    }
}

public enum ConversationServerMessage: Decodable, Equatable, Sendable {
    case snapshot(ConversationSnapshot)
    case itemsUpserted(generation: String, revision: UInt64, items: [ConversationItem])
    case itemsRemoved(generation: String, revision: UInt64, itemIds: [String])
    case stateChanged(generation: String, revision: UInt64, state: ConversationState)
    case operationResult(operationId: String, status: String, itemId: String?, reason: String?)
    case historyPage(requestId: String, items: [ConversationItem], hasMoreBefore: Bool)
    case error(code: String, message: String)

    private enum CodingKeys: String, CodingKey {
        case type, generation, revision, operationEpoch, items, state, hasMoreBefore, reason
        case itemIds, operationId, status, itemId, requestId, code, message
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        switch try container.decode(String.self, forKey: .type) {
        case "snapshot": self = .snapshot(try ConversationSnapshot(from: decoder))
        case "items_upserted": self = .itemsUpserted(
            generation: try container.decode(String.self, forKey: .generation),
            revision: try container.decode(UInt64.self, forKey: .revision),
            items: try container.decodeConversationItems(forKey: .items)
        )
        case "items_removed": self = .itemsRemoved(
            generation: try container.decode(String.self, forKey: .generation),
            revision: try container.decode(UInt64.self, forKey: .revision),
            itemIds: try container.decode([String].self, forKey: .itemIds)
        )
        case "state_changed": self = .stateChanged(
            generation: try container.decode(String.self, forKey: .generation),
            revision: try container.decode(UInt64.self, forKey: .revision),
            state: try container.decode(ConversationState.self, forKey: .state)
        )
        case "operation_result": self = .operationResult(
            operationId: try container.decode(String.self, forKey: .operationId),
            status: try container.decode(String.self, forKey: .status),
            itemId: try container.decodeIfPresent(String.self, forKey: .itemId),
            reason: try container.decodeIfPresent(String.self, forKey: .reason)
        )
        case "history_page": self = .historyPage(
            requestId: try container.decode(String.self, forKey: .requestId),
            items: try container.decodeConversationItems(forKey: .items),
            hasMoreBefore: try container.decode(Bool.self, forKey: .hasMoreBefore)
        )
        case "error": self = .error(
            code: try container.decode(String.self, forKey: .code),
            message: try container.decode(String.self, forKey: .message)
        )
        default: throw DecodingError.dataCorruptedError(forKey: .type, in: container, debugDescription: "unknown server message")
        }
    }
}

public enum ConversationClientMessage: Encodable, Equatable, Sendable {
    case resume(generation: String?, afterRevision: UInt64?)
    case sendMessage(operationEpoch: String, operationId: String, text: String)
    case cancelTurn(operationEpoch: String, operationId: String)
    case resolveRequest(operationEpoch: String, operationId: String, requestId: String, choice: String? = nil, answers: [String: String]? = nil)
    case historyRequest(requestId: String, beforeOrdinal: UInt64, limit: Int)
    case operationStatus(operationId: String)

    private enum CodingKeys: String, CodingKey {
        case type, generation, afterRevision, operationEpoch, operationId, text
        case requestId, choice, answers, beforeOrdinal, limit
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .resume(let generation, let afterRevision):
            try container.encode("resume", forKey: .type)
            try container.encodeIfPresent(generation, forKey: .generation)
            try container.encodeIfPresent(afterRevision, forKey: .afterRevision)
        case .sendMessage(let operationEpoch, let operationId, let text):
            try container.encode("send_message", forKey: .type)
            try container.encode(operationEpoch, forKey: .operationEpoch)
            try container.encode(operationId, forKey: .operationId)
            try container.encode(text, forKey: .text)
        case .cancelTurn(let operationEpoch, let operationId):
            try container.encode("cancel_turn", forKey: .type)
            try container.encode(operationEpoch, forKey: .operationEpoch)
            try container.encode(operationId, forKey: .operationId)
        case .resolveRequest(let operationEpoch, let operationId, let requestId, let choice, let answers):
            try container.encode("resolve_request", forKey: .type)
            try container.encode(operationEpoch, forKey: .operationEpoch)
            try container.encode(operationId, forKey: .operationId)
            try container.encode(requestId, forKey: .requestId)
            try container.encodeIfPresent(choice, forKey: .choice)
            try container.encodeIfPresent(answers, forKey: .answers)
        case .historyRequest(let requestId, let beforeOrdinal, let limit):
            try container.encode("history_request", forKey: .type)
            try container.encode(requestId, forKey: .requestId)
            try container.encode(beforeOrdinal, forKey: .beforeOrdinal)
            try container.encode(limit, forKey: .limit)
        case .operationStatus(let operationId):
            try container.encode("operation_status", forKey: .type)
            try container.encode(operationId, forKey: .operationId)
        }
    }
}
